import { Table, StringColumn, BooleanColumn, GenericColumn } from '../../db'

export const sys_script_include = Table({
    name: 'sys_script_include',
    extends: 'sys_metadata',
    schema: {
        access: StringColumn({
            mandatory: false,
            label: 'Accessible from',
            read_only: false,
            active: true,
            default: 'package_private',
            maxLength: 40,
            dropdown: 'dropdown_without_none',
            choices: {
                package_private: { label: 'This application scope only', inactive: false, language: 'en' },
                public: { label: 'All application scopes', inactive: false, language: 'en' },
            },
        }),
        active: BooleanColumn({
            mandatory: false,
            label: 'Active',
            read_only: false,
            active: true,
            default: true,
            maxLength: 40,
        }),
        api_name: StringColumn({
            mandatory: false,
            label: 'API Name',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        caller_access: StringColumn({
            mandatory: false,
            label: 'Caller Access',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'dropdown_with_none',
            choices: {
                1: { label: 'Caller Tracking', inactive: false, language: 'en' },
                2: { label: 'Caller Restriction', inactive: false, language: 'en' },
            },
        }),
        client_callable: BooleanColumn({
            mandatory: false,
            label: 'Glide AJAX enabled',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: false,
            active: true,
            maxLength: 4000,
            dropdown: 'none',
        }),
        mobile_callable: BooleanColumn({
            mandatory: false,
            label: 'Mobile callable',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        sandbox_callable: BooleanColumn({
            mandatory: false,
            label: 'Sandbox enabled',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        script: GenericColumn({
            mandatory: false,
            label: 'Script',
            read_only: false,
            active: true,
            maxLength: 8000,
            column_type: 'script_plain',
        }),
    },
})
